  ('bf93f26f-5570-43fd-b42b-e6ac0b457fc6', 202602, '202602-023', 'salida_definitiva', 'nota_credito', 'sin_existencias', '6204', 'SAN JOSÉ', 'R&A SOLUCIONES ELECTROMECÁNICAS SA', '144762', 1, '2026-02-26', 'HIKVISION', 'DS2CD1323G2-LIU28', '', 'El equipo ingresa por no encender. Tras verificar y realizar mediciones internas, se detecta un componente defectuoso que impide su funcionamiento. Se concluye que la falla corresponde a un defecto de fábrica.', '2026-02-26T00:00:00+00:00', NULL, NULL, NULL, NULL, 'Matthew Bermúdez', NULL, NULL, 'GE2113929', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false),
